('math_fraction_quest', 'สองสูตรขนมปัง', '{"icon":"🥖","story":["สูตร A ใช้แป้งสาลี 1/7 ถ้วย และแป้งข้าว 1/6 ถ้วย","สูตร B ใช้แป้งสาลี 1 ถ้วย และแป้งข้าว 1/6 ถ้วย","ทั้งสองสูตรอบที่ 180 องศาเซลเซียส นาน 25 นาที"],"context":[],"steps":[{"kind":"fraction","prompt":"สูตร A ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["หา ค.ร.น. ของ 7 และ 6"],"solution":["ค.ร.น. ของ 7 และ 6 คือ 42","1/7 + 1/6 = 6/42 + 7/42 = 13/42"],"answer":{"n":13,"d":42},"unit":"ถ้วย"},{"kind":"fraction","prompt":"สูตร B ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["1 = 6/6"],"solution":["1 + 1/6 = 1 1/6 ถ้วย"],"answer":{"n":7,"d":6},"unit":"ถ้วย"},{"kind":"choice","prompt":"สูตรใดใช้แป้งน้อยกว่า","skill":"analysis","points":10,"hints":[],"solution":["13/42 < 1 1/6"],"options":[{"text":"สูตร A","ok":true,"why":"13/42 กับ 1 1/6 ทำตัวส่วนให้เท่ากันแล้วเทียบ"},{"text":"สูตร B","ok":false,"why":"13/42 กับ 1 1/6 ทำตัวส่วนให้เท่ากันแล้วเทียบ"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"สูตรที่ใช้แป้งน้อยกว่า ประหยัดแป้งได้กี่ถ้วย","skill":"final","points":10,"hints":["นำปริมาณที่มากกว่าลบปริมาณที่น้อยกว่า"],"solution":["ค.ร.น. ของ 6 และ 42 คือ 42","1 1/6 − 13/42 = 49/42 − 13/42 = 6/7"],"answer":{"n":6,"d":7},"unit":"ถ้วย"}]}', 'challenge', 76),
('math_fraction_quest', 'ร้านเค้กวันเด็ก', '{"icon":"🎂","story":["เค้ก 1 ก้อนใช้น้ำตาล 2/9 กิโลกรัม ต้องทำ 4 ก้อน","ร้านมีน้ำตาล 4 กิโลกรัม และมีไข่ 30 ฟอง"],"context":[],"steps":[{"kind":"fraction","prompt":"ทำเค้ก 4 ก้อน ต้องใช้น้ำตาลกี่กิโลกรัม","skill":"calculation","points":10,"hints":["คูณเศษส่วนกับจำนวนนับ: คูณเฉพาะตัวเศษ"],"solution":["2/9 × 4 = 8/9 = 8/9 กิโลกรัม"],"answer":{"n":8,"d":9},"unit":"กิโลกรัม"},{"kind":"fraction","prompt":"น้ำตาลเหลือกี่กิโลกรัม","skill":"calculation","points":10,"hints":["นำปริมาณที่มากกว่าลบปริมาณที่น้อยกว่า"],"solution":["ค.ร.น. ของ 1 และ 9 คือ 9","4 − 8/9 = 36/9 − 8/9 = 3 1/9"],"answer":{"n":28,"d":9},"unit":"กิโลกรัม"},{"kind":"number","prompt":"ด้วยน้ำตาลที่มี ทำเค้กได้มากที่สุดกี่ก้อน","skill":"planning","points":10,"hints":["หาว่า 4 มี 2/9 อยู่กี่ส่วนเต็ม","4 = 36/9 แล้วหารด้วย 2"],"solution":["4 = 36/9 กิโลกรัม","36 ÷ 2 = 18 ทำได้เต็มก้อน 18 ก้อน"],"answer":18,"unit":"ก้อน"}]}', 'challenge', 77),
('math_fraction_quest', 'ห่อของขวัญวันเกิด', '{"icon":"🎀","story":["มีริบบิ้นยาว 2 เมตร ราคาเมตรละ 19 บาท","ผูกกล่องของขวัญ 3 ใบ ใช้ 5/7 เมตร, 4/7 เมตร, 7/12 เมตร"],"context":[],"steps":[{"kind":"choice","prompt":"ข้อมูลใดไม่จำเป็นต่อการหาความยาวริบบิ้นที่เหลือ","skill":"analysis","points":5,"hints":[],"solution":["คำถามถามความยาว ไม่เกี่ยวกับราคา"],"options":[{"text":"ราคาริบบิ้นเมตรละ 19 บาท","ok":true,"why":""},{"text":"ความยาวที่ใช้ผูกกล่องแต่ละใบ","ok":false,"why":"ต้องใช้หาความยาวที่ใช้ไปทั้งหมด"},{"text":"ความยาวริบบิ้นที่มี 2 เมตร","ok":false,"why":"ต้องใช้ความยาวที่มีเป็นตัวตั้ง"}],"answer":0},{"kind":"fraction","prompt":"ใช้ริบบิ้นไปทั้งหมดกี่เมตร","skill":"calculation","points":10,"hints":["ทำตัวส่วนให้เท่ากันเป็น 84","60/84 + 48/84 + 49/84"],"solution":["ทำตัวส่วนให้เท่ากันเป็น 84: 5/7 = 60/84, 4/7 = 48/84, 7/12 = 49/84","บวกตัวเศษ: 60 + 48 + 49 = 157 จึงได้ 157/84 = 1 73/84 เมตร"],"answer":{"n":157,"d":84},"unit":"เมตร","mistakes":[{"value":{"n":8,"d":13},"why":"บวกตัวส่วนเข้าด้วยกันไม่ได้ ต้องทำตัวส่วนให้เท่ากันก่อน"}]},{"kind":"fraction","prompt":"เหลือริบบิ้นกี่เมตร","skill":"final","points":10,"hints":["2 − 1 73/84","2 = 168/84"],"solution":["2 − 1 73/84 = 168/84 − 157/84 = 11/84 เมตร"],"answer":{"n":11,"d":84},"unit":"เมตร"},{"kind":"choice","prompt":"ต้องเก็บริบบิ้นอย่างน้อย 1/2 เมตรไว้ผูกโบว์ใหญ่ ริบบิ้นที่เหลือพอหรือไม่","skill":"final","points":10,"hints":[],"solution":["เทียบ 11/84 กับ 1/2 โดยทำตัวส่วนเป็น 84"],"options":[{"text":"พอ","ok":false,"why":"11/84 = 11/84 น้อยกว่า 1/2 = 42/84"},{"text":"ไม่พอ","ok":true,"why":"11/84 = 11/84 ไม่น้อยกว่า 1/2 = 42/84"}],"answer":1,"keepOrder":true}]}', 'challenge', 78),
('math_fraction_quest', 'ตรวจการบ้านเพื่อน', '{"icon":"📝","story":["ก้องคิดว่า 8/9 + 7/12 = 15/21 โดยบวกตัวเศษกับตัวเศษ และตัวส่วนกับตัวส่วน"],"context":[],"steps":[{"kind":"choice","prompt":"วิธีของก้องถูกหรือไม่","skill":"planning","points":10,"hints":[],"solution":["เศษส่วนบวกกันได้เมื่อแบ่งเป็นส่วนขนาดเท่ากัน จึงต้องทำตัวส่วนให้เท่ากันก่อน"],"options":[{"text":"ผิด เพราะต้องทำตัวส่วนให้เท่ากันก่อน แล้วบวกเฉพาะตัวเศษ","ok":true,"why":""},{"text":"ถูก เพราะบวกทั้งตัวเศษและตัวส่วนครบแล้ว","ok":false,"why":"ลองเช็ก: 1/2 + 1/2 ต้องได้ 1 แต่วิธีนี้ได้ 2/4 = 1/2"},{"text":"ถูก ถ้าตัดทอนเป็นเศษส่วนอย่างต่ำก่อน","ok":false,"why":"การตัดทอนไม่ช่วย เพราะการบวกตัวส่วนผิดตั้งแต่ต้น"}],"answer":0},{"kind":"fraction","prompt":"คำตอบที่ถูกต้องของ 8/9 + 7/12 คือเท่าไร","skill":"calculation","points":10,"hints":["หา ค.ร.น. ของ 9 และ 12","32/36 + 21/36"],"solution":["ค.ร.น. ของ 9 และ 12 คือ 36","8/9 + 7/12 = 32/36 + 21/36 = 1 17/36"],"answer":{"n":53,"d":36},"mistakes":[{"value":{"n":5,"d":7},"why":"นี่คือคำตอบที่ผิดแบบเดียวกับเพื่อน"}]},{"kind":"choice","prompt":"ตรวจด้วยการประมาณ: ผลบวกที่ถูกต้องต้องมากกว่า 8/9 หรือไม่","skill":"analysis","points":5,"hints":[],"solution":["15/21 ไม่มากกว่า 8/9 จึงเป็นไปไม่ได้"],"options":[{"text":"ต้องมากกว่า เพราะบวกจำนวนที่มากกว่า 0 เข้าไป และคำตอบของก้องไม่มากกว่า จึงผิดแน่นอน","ok":true,"why":""},{"text":"ไม่จำเป็นต้องมากกว่า","ok":false,"why":"การบวกจำนวนบวกเพิ่มเข้าไป ผลลัพธ์ต้องมากกว่าตัวตั้งเสมอ"}],"answer":0,"keepOrder":true},{"kind":"fraction","prompt":"คำตอบของก้องน้อยกว่าคำตอบที่ถูกอยู่เท่าไร","skill":"final","points":10,"hints":["1 17/36 − 5/7"],"solution":["ค.ร.น. ของ 36 และ 7 คือ 252","1 17/36 − 5/7 = 371/252 − 180/252 = 191/252"],"answer":{"n":191,"d":252}}]}', 'challenge', 79),
('math_fraction_quest', 'สองสูตรขนมปัง', '{"icon":"🥖","story":["สูตร A ใช้แป้งสาลี 11/12 ถ้วย และแป้งข้าว 5/6 ถ้วย","สูตร B ใช้แป้งสาลี 1 ถ้วย และแป้งข้าว 1/4 ถ้วย","ทั้งสองสูตรอบที่ 180 องศาเซลเซียส นาน 25 นาที"],"context":[],"steps":[{"kind":"fraction","prompt":"สูตร A ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["หา ค.ร.น. ของ 12 และ 6"],"solution":["ค.ร.น. ของ 12 และ 6 คือ 12","11/12 + 5/6 = 11/12 + 10/12 = 1 3/4"],"answer":{"n":7,"d":4},"unit":"ถ้วย"},{"kind":"fraction","prompt":"สูตร B ใช้แป้งรวมกี่ถ้วย","skill":"calculation","points":10,"hints":["1 = 4/4"],"solution":["1 + 1/4 = 1 1/4 ถ้วย"],"answer":{"n":5,"d":4},"unit":"ถ้วย"},{"kind":"choice","prompt":"สูตรใดใช้แป้งน้อยกว่า","skill":"analysis","points":10,"hints":[],"solution":["1 3/4 > 1 1/4"],"options":[{"text":"สูตร A","ok":false,"why":"1 3/4 กับ 1 1/4 ทำตัวส่วนให้เท่ากันแล้วเทียบ"},{"text":"สูตร B","ok":true,"why":"1 3/4 กับ 1 1/4 ทำตัวส่วนให้เท่ากันแล้วเทียบ"}],"answer":1,"keepOrder":true},{"kind":"fraction","prompt":"สูตรที่ใช้แป้งน้อยกว่า ประหยัดแป้งได้กี่ถ้วย","skill":"final","points":10,"hints":["นำปริมาณที่มากกว่าลบปริมาณที่น้อยกว่า"],"solution":["ค.ร.น. ของ 4 และ 4 คือ 4","1 3/4 − 1 1/4 = 7/4 − 5/4 = 1/2"],"answer":{"n":1,"d":2},"unit":"ถ้วย"}]}', 'challenge', 80),
('math_decimal_shop', 'จ่ายตลาดให้คุณแม่', '{"icon":"🧺","story":["คุณแม่ให้เงิน 140.00 บาท และรายการที่ต้องซื้อ: กล้วยหอม 2 หวี, นมกล่อง 2 กล่อง"],"context":[{"type":"table","title":"🏷️ ป้ายราคา","head":["สินค้า","ราคา (บาท)","รายละเอียด"],"rows":[["กล้วยหอม (หวี)","42.75","หวีละ 6 ลูก"],["นมกล่อง (กล่อง)","20.75","ขนาด 200 มิลลิลิตร"]]}],"steps":[{"kind":"fixed","prompt":"ซื้อกล้วยหอม 2 หวี เป็นเงินกี่บาท","skill":"calculation","points":10,"hints":["42.75 × 2"],"solution":["42.75 × 2 = 85.50 บาท"],"answer":8550,"places":2,"unit":"บาท","money":true},{"kind":"fixed","prompt":"ราคารวมของทั้งตะกร้าเป็นเงินกี่บาท","skill":"analysis","points":10,"hints":["หาราคาแต่ละรายการ (ราคา × จำนวน) แล้วบวกกัน","ตั้งจุดทศนิยมให้ตรงกันก่อนบวก"],"solution":["กล้วยหอม: 42.75 × 2 = 85.50","นมกล่อง: 20.75 × 2 = 41.50","รวม 85.50 + 41.50 = 127.00 บาท"],"answer":12700,"places":2,"unit":"บาท","money":true},{"kind":"choice","prompt":"มีงบ 140.00 บาท พอซื้อทั้งหมดหรือไม่","skill":"planning","points":10,"hints":[],"solution":["127.00 < 140.00"],"options":[{"text":"พอ","ok":true,"why":"ราคารวม 127.00 มากกว่างบ 140.00"},{"text":"ไม่พอ","ok":false,"why":"ราคารวม 127.00 ไม่เกินงบ 140.00"}],"answer":0,"keepOrder":true},{"kind":"fixed","prompt":"จะได้รับเงินทอนกี่บาท","skill":"final","points":10,"hints":["นำจำนวนที่มากกว่าลบจำนวนที่น้อยกว่า"],"solution":["140.00 − 127.00 = 13.00 บาท (ตั้งจุดทศนิยมให้ตรงกัน)"],"answer":1300,"places":2,"unit":"บาท","money":true}]}', 'easy', 1),
('math_decimal_shop', 'โปรโมชันคุ้มจริงไหม', '{"icon":"🏷️","story":["ต้องซื้อปากกา 5 ด้าม สำหรับงานเลี้ยงห้อง","ราคาด้ามละ 16.00 บาท หรือโปรโมชันแพ็ก 3 ด้าม ราคา 47.00 บาท"],"context":[{"type":"note","text":"แผน A: ซื้อทีละด้าม 5 ด้าม · แผน B: ซื้อแพ็ก 3 ให้มากที่สุด ที่ขาดซื้อทีละด้าม"},{"type":"note","text":"ข้อมูลอื่น: หมึกสีน้ำเงิน และร้านเปิด 08.30 น."}],"steps":[{"kind":"fixed","prompt":"แผน A ต้องจ่ายกี่บาท","skill":"calculation","points":10,"hints":["16.00 × 5"],"solution":["16.00 × 5 = 80.00 บาท"],"answer":8000,"places":2,"unit":"บาท","money":true},{"kind":"number","prompt":"แผน B ซื้อแพ็ก 3 ได้กี่แพ็ก","skill":"planning","points":10,"hints":["5 ÷ 3 เอาเฉพาะส่วนเต็ม"],"solution":["5 ÷ 3 = 1 เศษ 2 จึงซื้อ 1 แพ็ก และซื้อเพิ่มทีละด้าม 2 ด้าม"],"answer":1,"unit":"แพ็ก"},{"kind":"fixed","prompt":"แผน B ต้องจ่ายกี่บาท","skill":"calculation","points":10,"hints":["ราคาแพ็ก × จำนวนแพ็ก แล้วบวกราคาที่ซื้อเพิ่มทีละชิ้น"],"solution":["47.00 × 1 + 16.00 × 2 = 79.00 บาท"],"answer":7900,"places":2,"unit":"บาท","money":true},{"kind":"choice","prompt":"แผนใดคุ้มกว่า และถูกกว่ากี่บาท","skill":"final","points":15,"hints":[],"solution":["|80.00 − 79.00| = 1.00 บาท แผน B ถูกกว่า"],"options":[{"text":"แผน A ถูกกว่า 1.00 บาท","ok":false,"why":"แผน A 80.00 เทียบแผน B 79.00"},{"text":"แผน B ถูกกว่า 1.00 บาท","ok":true,"why":"แผน A 80.00 เทียบแผน B 79.00"},{"text":"แผน B ถูกกว่า 2.00 บาท","ok":false,"why":"ผลต่างคือ 80.00 กับ 79.00 ลบกัน"},{"text":"โปรโมชันถูกกว่าเสมอ ไม่ต้องคำนวณ","ok":false,"why":"โปรโมชันบางแบบไม่คุ้ม ต้องคำนวณเทียบทุกครั้ง"}],"answer":1,"keepOrder":true}]}', 'easy', 2),
